            <TableRow
              key={data[virtualRow.index].id}
              row={data[virtualRow.index]}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualRow.start}px)`,
                height: `${virtualRow.size}px`,
              }}
            />
          ))}
        </div>
      </div>

      <TableFooter totalCount={data.length} />
