## معالجة البيانات: لا تُعالج 4,000 صف في الـ Render

```tsx
// hooks/useMetricsData.ts
import { useMemo, useTransition, useState } from 'react';

interface FilterState {
  search: string;
  status: 'all' | 'up' | 'down' | 'stable';
  sortKey: keyof MetricRow;
  sortDir: 'asc' | 'desc';
}

export function useMetricsData(rawData: MetricRow[]) {
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    status: 'all',
    sortKey: 'name',
    sortDir: 'asc',
  });

  // useTransition: يُبقي الـ UI مستجيباً أثناء الفلترة
  const [isPending, startTransition] = useTransition();

  const updateFilter = useCallback(
    <K extends keyof FilterState>(key: K, value: FilterState[K]) => {
      startTransition(() => {
        setFilters((prev) => ({ ...prev, [key]: value }));
      });
    },
    []
  );

  // useMemo: لا تُعيد الحساب إلا عند تغيير البيانات أو الفلاتر
  const processedData = useMemo(() => {
    let result = rawData;

    // 1. فلترة النص
    if (filters.search.trim()) {
      const query = filters.search.toLowerCase();
      result = result.filter((row) => row.name.toLowerCase().includes(query));
    }

    // 2. فلترة الحالة
    if (filters.status !== 'all') {
      result = result.filter((row) => row.status === filters.status);
    }

    // 3. الترتيب
    result = [...result].sort((a, b) => {
      const aVal = a[filters.sortKey];
      const bVal = b[filters.sortKey];
      const order = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      return filters.sortDir === 'asc' ? order : -order;
    });

    return result;
  }, [rawData, filters]);

  return { processedData, filters, updateFilter, isPending };
}
```

