// ─── فصل جلب البيانات عن العرض ────────────────────────────────────────────
function MetricsTableContainer() {
  const { data, isLoading, error } = useMetrics({
    // جلب أول 100 صف فقط في البداية
    initialPageSize: 100,
    // باقي البيانات تُجلب في الخلفية
    backgroundFetch: true,
  });

  if (error) return <ErrorState error={error} />;

  return <MetricsTable data={data} isLoading={isLoading} />;
}
