    super.onCreate()

    // بعض الشركات تُعيد تعريف هذا السلوك
    val config = resources.configuration
    val locale = config.locales.get(0) // API 24+
    // على بعض أجهزة Huawei القديمة: config.locale (deprecated)
    // النتيجة: استثناء غير متوقع
}
