## خطة التشخيص المنهجية

### الخطوة 1 — احصل على Stacktrace الحقيقي

```kotlin
// في Application.onCreate() — قبل أي شيء آخر
class MyApp : Application() {
    override fun onCreate() {
        // هذا أولاً
        setupCrashHandler()
        super.onCreate()
        // باقي الكود
    }

    private fun setupCrashHandler() {
        val defaultHandler = Thread.getDefaultUncaughtExceptionHandler()
        Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->
            // سجّل في ملف محلي قبل أن يموت التطبيق
            saveStackTraceToFile(throwable)
            defaultHandler?.uncaughtException(thread, throwable)
        }
    }

    private fun saveStackTraceToFile(throwable: Throwable) {
        try {
            val file = File(filesDir, "crash_log.txt")
            file.writeText(throwable.stackTraceToString())
        } catch (e: Exception) { /* تجاهل */ }
    }
}
```

