    val featureFlags: Map<String, Boolean>,
    val apiVersion: Int,
    val theme: String
)

// في الكود
val config = Gson().fromJson(jsonString, UserConfig::class.java)
// config.featureFlags سيكون null دائماً في الإنتاج!
```

