## الحلول

### 1. الحل الفوري — جعل تاريخ الاستحقاق ديناميكياً

```typescript
// ❌ الكود الحالي (هش)
const invoice = await createInvoice({
  due_date: "2024-01-19", // تاريخ ثابت سيصبح في الماضي
});

// ✅ الحل: احسب التاريخ نسبةً إلى "الآن"
import { startOfWeek, endOfWeek, addDays } from "date-fns";

function getDueDateWithinCurrentWeek(): string {
  const now = new Date();
  const weekEnd = endOfWeek(now, { weekStartsOn: 1 }); // ISO: الأسبوع يبدأ الاثنين

  // استخدم نهاية الأسبوع الحالي كتاريخ استحقاق
  return format(weekEnd, "yyyy-MM-dd");
}

const invoice = await createInvoice({
  due_date: getDueDateWithinCurrentWeek(),
});
```

### 2. الحل الصحيح — التحكم في "الوقت الحالي" داخل التطبيق

```typescript
// في كود التطبيق: لا تستخدم new Date() مباشرة
// بدلاً من ذلك، اجعل مصدر الوقت قابلاً للحقن

// clock.ts
export interface Clock {
  now(): Date;
}

export const systemClock: Clock = {
  now: () => new Date(),
};

// invoice.service.ts
export class InvoiceService {
  constructor(private clock: Clock = systemClock) {}

  getInvoicesDueThisWeek(invoices: Invoice[]): Invoice[] {
    const now = this.clock.now(); // ✅ وليس new Date()
    const weekStart = startOfWeek(now, { weekStartsOn: 1 });
    const weekEnd = endOfWeek(now, { weekStartsOn: 1 });

    return invoices.filter((inv) => {
      const due = parseISO(inv.due_date);
      return isWithinInterval(due, { start: weekStart, end: weekEnd });
    });
  }
}
```

```typescript
// في الاختبار: تحكم كامل في الوقت
describe("invoices due this week", () => {
  it("shows invoice created with due date in current ISO week", async () => {
    // ✅ ثبّت الوقت بشكل صريح
    const frozenNow = new Date("2024-01-17T10:00:00Z"); // أربعاء، منتصف الأسبوع
    const fakeClock: Clock = { now: () => frozenNow };

    const service = new InvoiceService(fakeClock);

    const invoice = await createInvoice({
      due_date: "2024-01-19", // جمعة من نفس الأسبوع المثبّت
    });

    const result = service.getInvoicesDueThisWeek([invoice]);
    expect(result).toContainEqual(expect.objectContaining({ id: invoice.id }));
  });
});
```

### 3. للاختبارات E2E — استخدم متغير بيئة لتثبيت الوقت

```typescript
// في إعداد الاختبار (e2e setup)
beforeAll(async () => {
  // أخبر الخادم بالوقت "المثبّت"
  await request(app)
    .post("/__test__/freeze-time")
    .send({ timestamp: "2024-01-17T10:00:00Z" });
});

afterAll(async () => {
  await request(app).post("/__test__/unfreeze-time");
});
```

```typescript
// middleware يعمل فقط في بيئة الاختبار
if (process.env.NODE_ENV === "test") {
  let frozenTime: Date | null = null;

  app.post("/__test__/freeze-time", (req, res) => {
    frozenTime = new Date(req.body.timestamp);
    res.sendStatus(200);
  });

  app.post("/__test__/unfreeze-time", (req, res) => {
    frozenTime = null;
    res.sendStatus(200);
  });

  // استبدل Clock العالمي
  globalClock.now = () => frozenTime ?? new Date();
}
```

