  // تحويل إلى JPEG قبل الرفع
  const processed = await manipulateAsync(
    imageUri,
    [{ resize: { width: 1200 } }], // تقليل الحجم أيضاً
    { 
      compress: 0.8, 
      format: SaveFormat.JPEG 
    }
  );
  return processed.uri;
};
