  }, [uri]);

  const isValidUrl = (url) => {
    try {
      new URL(url);
      return url.startsWith('http://') || url.startsWith('https://');
    } catch {
      return false;
    }
  };

  if (error || !imageUri) {
    return <Image source={fallback} />;
