## الحل الشامل المقترح

```javascript
import React, { useState, useCallback } from 'react';
import { View, ActivityIndicator, TouchableOpacity, Text } from 'react-native';
import FastImage from 'react-native-fast-image';

const UserUploadedImage = ({ 
  uri, 
  style, 
  fallbackSource,
  maxWidth = 800 // تحديد حجم أقصى
}) => {
  const [status, setStatus] = useState('loading'); // loading | success | error

  // تنظيف الـ URI - iOS حساس جداً
  const cleanUri = useCallback((rawUri) => {
    if (!rawUri) return null;

    // إزالة مسافات
    const trimmed = rawUri.trim();

    // التأكد من HTTPS (iOS يرفض HTTP بدون إعداد خاص)
    if (trimmed.startsWith('http://')) {
      console.warn('HTTP image URL detected - may fail on iOS');
    }

    return trimmed;
  }, []);

  const cleanedUri = cleanUri(uri);

  if (!cleanedUri) {
    return <FastImage source={fallbackSource} style={style} />;
  }

  return (
    <View style={style}>
      <FastImage
        source={{
          uri: cleanedUri,
          priority: FastImage.priority.normal,
          // تحديد headers إذا احتجت
          headers: { Accept: 'image/jpeg,image/png,image/*' },
        }}
        style={[style, { position: 'absolute' }]}
        resizeMode={FastImage.resizeMode.cover}
        onLoadStart={() => setStatus('loading')}
        onLoad={() => setStatus('success')}
        onError={() => setStatus('error')}
      />

      {status === 'loading' && (
        <ActivityIndicator style={{ position: 'absolute', alignSelf: 'center' }} />
      )}

      {status === 'error' && (
        <FastImage source={fallbackSource} style={style} />
      )}
    </View>
  );
};

export default UserImageScreen;
```

