### 2. معالج الصور المحلي (بدون CDN)

```javascript
// utils/ImageProcessor.js
import { Image } from 'react-native';
import * as FileSystem from 'expo-file-system'; // أو react-native-fs
import * as ImageManipulator from 'expo-image-manipulator';

class ImageProcessor {
  constructor() {
    this.cache = new Map();
    this.processingQueue = new Map();
    this.MAX_CACHE_SIZE = 20;
    this.MAX_DIMENSION = 1024;
  }

  /**
   * الحصول على صورة محسّنة - مع تخزين مؤقت ذكي
   */
  async getOptimizedImage(uri, targetWidth, targetHeight) {
    const cacheKey = `${uri}_${targetWidth}x${targetHeight}`;

    // التحقق من الكاش أولاً
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    // منع المعالجة المتكررة لنفس الصورة
    if (this.processingQueue.has(cacheKey)) {
      return this.processingQueue.get(cacheKey);
    }

    // بدء المعالجة
    const processingPromise = this._processImage(uri, targetWidth, targetHeight, cacheKey);
    this.processingQueue.set(cacheKey, processingPromise);

    try {
      const result = await processingPromise;
      return result;
    } finally {
      this.processingQueue.delete(cacheKey);
    }
  }

  async _processImage(uri, targetWidth, targetHeight, cacheKey) {
    try {
      // الحصول على أبعاد الصورة الأصلية
      const originalSize = await this._getImageSize(uri);

      // التحقق إذا كانت الصورة تحتاج تحجيماً
      if (
        originalSize.width <= targetWidth &&
        originalSize.height <= targetHeight
      ) {
        // الصورة صغيرة بالفعل، لا حاجة للمعالجة
        this._addToCache(cacheKey, uri);
        return uri;
      }

      // حساب الأبعاد مع الحفاظ على النسبة
      const { width, height } = this._calculateFitDimensions(
        originalSize.width,
        originalSize.height,
        targetWidth,
        targetHeight
      );

      // معالجة الصورة
      const manipResult = await ImageManipulator.manipulateAsync(
        uri,
        [{ resize: { width, height } }],
        {
          compress: 0.85,
          format: ImageManipulator.SaveFormat.JPEG,
          base64: false,
        }
      );

      this._addToCache(cacheKey, manipResult.uri);
      return manipResult.uri;

    } catch (error) {
      console.error('Image processing failed:', error);
      return uri; // fallback للصورة الأصلية
    }
  }

  _getImageSize(uri) {
    return new Promise((resolve, reject) => {
      Image.getSize(
        uri,
        (width, height) => resolve({ width, height }),
        reject
      );
    });
  }

  _calculateFitDimensions(srcWidth, srcHeight, maxWidth, maxHeight) {
    const widthRatio = maxWidth / srcWidth;
    const heightRatio = maxHeight / srcHeight;
    const ratio = Math.min(widthRatio, heightRatio);

    return {
      width: Math.round(srcWidth * ratio),
      height: Math.round(srcHeight * ratio),
    };
  }

  _addToCache(key, value) {
    // إزالة أقدم عنصر إذا امتلأ الكاش
    if (this.cache.size >= this.MAX_CACHE_SIZE) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    this.cache.set(key, value);
  }

  /**
   * تنظيف الكاش عند ضغط الذاكرة
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * تنظيف جزئي - الاحتفاظ بأحدث N عنصر
   */
  trimCache(keepCount = 5) {
    const keys = Array.from(this.cache.keys());
    const toDelete = keys.slice(0, keys.length - keepCount);
    toDelete.forEach(key => this.cache.delete(key));
  }
}

export default new ImageProcessor(); // Singleton
```

