### 3. الشاشة المحسّنة مع إدارة دورة الحياة

```javascript
// screens/UserImageScreen.js
import React, {
  useState,
  useEffect,
  useCallback,
  useRef,
  useMemo,
} from 'react';
import {
  View,
  ScrollView,
  Dimensions,
  AppState,
  Platform,
  StyleSheet,
  InteractionManager,
} from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import SmartImage from '../components/SmartImage';
import ImageProcessor from '../utils/ImageProcessor';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

// الحد الأقصى للصور المحملة في الذاكرة في نفس الوقت
const MAX_VISIBLE_IMAGES = 3;

const UserImageScreen = ({ route }) => {
  const { images } = route.params;
  const [processedImages, setProcessedImages] = useState([]);
  const [isReady, setIsReady] = useState(false);
  const appStateRef = useRef(AppState.currentState);
  const isMountedRef = useRef(true);

  // معالجة الصور بعد اكتمال الانتقالات (لتجنب إبطاء الأنيميشن)
  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(async () => {
      if (!isMountedRef.current) return;

      const processed = await Promise.all(
        images.slice(0, MAX_VISIBLE_IMAGES).map(async (img) => {
          const optimizedUri = await ImageProcessor.getOptimizedImage(
            img.uri,
            SCREEN_WIDTH * 2,  // 2x للشاشات Retina
