// مع Node.js http — لتحديد مرحلة التأخير بدقة
import http from 'http';
import { performance } from 'perf_hooks';

function timedLoyaltyRequest(userId: string): Promise<LoyaltyData> {
  return new Promise((resolve, reject) => {
    const timings: Record<string, number> = {};
    const start = performance.now();

    const req = http.request(loyaltyApiOptions, (res) => {
      timings.firstByte = performance.now() - start;

      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        timings.total = performance.now() - start;

        // هذا يكشف: هل التأخير في DNS؟ TCP؟ أم في معالجة الطرف الثالث؟
        logger.warn('loyalty_slow_request', {
          userId,
          timings,
          isSlow: timings.total > 500,
        });

        resolve(JSON.parse(data));
      });
    });

    req.on('socket', (socket) => {
      socket.on('lookup',  () => timings.dns     = performance.now() - start);
      socket.on('connect', () => timings.connect = performance.now() - start);
      socket.on('secureConnect', () => timings.tls = performance.now() - start);
    });

    req.on('error', reject);
    req.end();
  });
}
