### الطبقة 2: الحل الفوري — Cache + Timeout

```typescript
// loyalty.service.ts
import { LRUCache } from 'lru-cache';

interface LoyaltyData {
  level: string;
  points: number;
  fetchedAt: number;
}

// Cache بمستويين
const loyaltyCache = new LRUCache<string, LoyaltyData>({
  max: 10_000,           // أقصى عدد مستخدمين
  ttl: 1000 * 60 * 5,   // 5 دقائق — اضبطها حسب معدل تغيّر الولاء
});

// Cache للحالات المتدهورة (stale-while-revalidate)
const staleCache = new LRUCache<string, LoyaltyData>({
  max: 10_000,
  ttl: 1000 * 60 * 60,  // ساعة كاملة للبيانات القديمة
});

export async function getLoyaltyLevel(userId: string): Promise<LoyaltyData> {
  // 1. تحقق من الـ cache الطازج
  const cached = loyaltyCache.get(userId);
  if (cached) {
    return { ...cached, source: 'cache' };
  }

  // 2. حاول الجلب مع timeout صارم
  try {
    const data = await fetchWithTimeout(userId, { timeoutMs: 800 });

    // خزّن في كلا الـ cache
    loyaltyCache.set(userId, data);
    staleCache.set(userId, data);

    return { ...data, source: 'api' };

  } catch (error) {
    // 3. Fallback للبيانات القديمة إن وُجدت
    const stale = staleCache.get(userId);
    if (stale) {
      logger.warn('loyalty_api_fallback_to_stale', { userId, error });
      return { ...stale, source: 'stale', isStale: true };
    }

    // 4. Fallback للقيمة الافتراضية — لا تُفشل الطلب بالكامل
    logger.error('loyalty_api_complete_failure', { userId, error });
    return getDefaultLoyaltyData(userId);
  }
}

async function fetchWithTimeout(
  userId: string,
  options: { timeoutMs: number }
): Promise<LoyaltyData> {
  const controller = new AbortController();
  const timeoutId = setTimeout(
    () => controller.abort(),
    options.timeoutMs
  );

  try {
    const response = await fetch(
      `${LOYALTY_API_BASE}/users/${userId}/level`,
      {
        signal: controller.signal,
        headers: {
          'Authorization': `Bearer ${LOYALTY_API_KEY}`,
          'Accept': 'application/json',
        },
        // أبقِ الاتصال حياً — يحل مشكلة TCP handshake المتكررة
        keepalive: true,
      }
    );

    if (!response.ok) {
      throw new LoyaltyApiError(response.status, await response.text());
    }

    return await response.json();
  } finally {
    clearTimeout(timeoutId);
  }
}
```

