### الطبقة 3: Background Refresh — إلغاء الانتظار كلياً

```typescript
// النمط: stale-while-revalidate
// المستخدم يحصل دائماً على استجابة فورية

class LoyaltyService {
  private cache = new Map<string, LoyaltyData>();
  private refreshQueue = new Set<string>(); // منع التحديثات المتزامنة

  async getLoyaltyLevel(userId: string): Promise<LoyaltyData> {
    const cached = this.cache.get(userId);

    if (cached) {
      const ageMs = Date.now() - cached.fetchedAt;

      // إذا البيانات قديمة — حدّثها في الخلفية بدون انتظار
      if (ageMs > 60_000 && !this.refreshQueue.has(userId)) {
        this.backgroundRefresh(userId); // لا await هنا
      }

      return cached; // استجابة فورية دائماً
    }

    // أول طلب للمستخدم — لا مفر من الانتظار
    return this.fetchAndCache(userId);
  }

  private async backgroundRefresh(userId: string): Promise<void> {
    this.refreshQueue.add(userId);

    try {
      await this.fetchAndCache(userId);
    } catch (error) {
      logger.warn('background_loyalty_refresh_failed', { userId, error });
      // فشل صامت — البيانات القديمة أفضل من لا شيء
    } finally {
      this.refreshQueue.delete(userId);
    }
  }

  private async fetchAndCache(userId: string): Promise<LoyaltyData> {
    const data = await fetchWithTimeout(userId, { timeoutMs: 3000 });
    this.cache.set(userId, { ...data, fetchedAt: Date.now() });
    return data;
  }
}
