### الطبقة 4: Circuit Breaker — حماية النظام

```typescript
// circuit-breaker.ts
type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

class CircuitBreaker {
  private state: CircuitState = 'CLOSED';
  private failureCount = 0;
  private lastFailureTime = 0;
  private successCount = 0;

  constructor(
    private readonly config: {
      failureThreshold: number;   // كم فشل قبل الفتح
      recoveryTimeMs: number;     // كم نانتظر قبل المحاولة
      halfOpenSuccessThreshold: number; // كم نجاح للإغلاق
    }
  ) {}

  async execute<T>(
    operation: () => Promise<T>,
    fallback: () => T
  ): Promise<T> {
    if (this.state === 'OPEN') {
      if (this.shouldAttemptRecovery()) {
        this.state = 'HALF_OPEN';
        logger.info('circuit_breaker_half_open');
      } else {
        // الدائرة مفتوحة — اذهب للـ fallback فوراً
        return fallback();
      }
    }

    try {
      const result = await operation();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      return fallback();
    }
  }

  private onSuccess(): void {
    this.failureCount = 0;

    if (this.state === 'HALF_OPEN') {
      this.successCount++;
      if (this.successCount >= this.config.halfOpenSuccessThreshold) {
        this.state = 'CLOSED';
        this.successCount = 0;
        logger.info('circuit_breaker_closed'); // الخدمة عادت
      }
    }
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.failureCount >= this.config.failureThreshold) {
      this.state = 'OPEN';
      logger.error('circuit_breaker_opened', {
        failureCount: this.failureCount,
      });
    }
  }

  private shouldAttemptRecovery(): boolean {
    return Date.now() - this.lastFailureTime > this.config.recoveryTimeMs;
  }
}

// الاستخدام
const loyaltyCircuitBreaker = new CircuitBreaker({
  failureThreshold: 5,
  recoveryTimeMs: 30_000,       // 30 ثانية
  halfOpenSuccessThreshold: 2,
});

export async function getLoyaltyLevelSafe(userId: string) {
  return loyaltyCircuitBreaker.execute(
    () => fetchWithTimeout(userId, { timeoutMs: 800 }),
    () => getDefaultLoyaltyData(userId) // fallback فوري
  );
}
```

