### الحل الثاني (موصى به): استدعاءات خارجية متوازية

```java
public class EnrichedMessageProcessor {

    private final ExternalEnrichmentService enrichmentService;
    // حجم Thread Pool = عدد المستهلكين × معامل التوازي المناسب
    private final ExecutorService enrichmentExecutor =
        Executors.newFixedThreadPool(24);

    public void processRecords(ConsumerRecords<String, Message> records) {

        // --- المرحلة 1: إطلاق جميع الاستدعاءات الخارجية بالتوازي ---
        Map<ConsumerRecord<String, Message>, CompletableFuture<EnrichedData>> futures =
            new LinkedHashMap<>();

        for (ConsumerRecord<String, Message> record : records) {
            CompletableFuture<EnrichedData> future = CompletableFuture
                .supplyAsync(
                    () -> enrichmentService.enrich(record.value()),
                    enrichmentExecutor
                )
                .orTimeout(5, TimeUnit.SECONDS)          // حد زمني صارم
                .exceptionally(ex -> {
                    log.warn("Enrichment failed for offset {}: {}",
                        record.offset(), ex.getMessage());
                    return EnrichedData.empty();          // قيمة افتراضية آمنة
                });

            futures.put(record, future);
        }

        // --- المرحلة 2: انتظار النتائج ومعالجتها ---
        futures.forEach((record, future) -> {
            try {
                EnrichedData enriched = future.get(6, TimeUnit.SECONDS);
                processEnrichedRecord(record, enriched);
            } catch (TimeoutException e) {
                log.error("Enrichment timed out for offset {}", record.offset());
                handleFailedRecord(record);
            } catch (Exception e) {
                log.error("Processing failed for offset {}", record.offset(), e);
                handleFailedRecord(record);
            }
        });
    }
}
```

