### الحل الثالث (الأمثل معمارياً): فصل الاستهلاك عن المعالجة

```
┌─────────────────────────────────────────────────────────────┐
│                    المعمارية المقترحة                        │
├─────────────────────────────────────────────────────────────┤
│                                                             │
│  Kafka Topic A          Internal Queue        Kafka Topic B │
│  (raw messages)                               (enriched)    │
│                                                             │
│  ┌──────────┐    poll    ┌─────────────┐                   │
│  │ Consumer │──────────▶│ BlockingQueue│                   │
│  │  Thread  │           │  (capacity  │                   │
│  │  (fast)  │           │   = 1000)   │                   │
│  └──────────┘           └──────┬──────┘                   │
│                                │                            │
│                    ┌───────────▼────────────┐              │
│                    │   Worker Thread Pool   │              │
│                    │  ┌──────┐ ┌──────┐    │              │
│                    │  │ W-1  │ │ W-2  │... │──▶ Topic B   │
│                    │  └──────┘ └──────┘    │              │
│                    └────────────────────────┘              │
└─────────────────────────────────────────────────────────────┘
```

```java
public class DecoupledConsumerProcessor {

    private final BlockingQueue<ConsumerRecord<String, Message>> workQueue =
        new LinkedBlockingQueue<>(1000);

    // --- خيط الاستهلاك: مسؤوليته الوحيدة هي poll() ---
    public void consumerLoop() {
        while (!shutdown) {
            ConsumerRecords<String, Message> records =
                consumer.poll(Duration.ofMillis(100));   // poll سريع دائماً

            for (ConsumerRecord<String, Message> record : records) {
                // عدم الحظر: إذا امتلأت القائمة نتوقف مؤقتاً
                boolean offered = workQueue.offer(record, 100, TimeUnit.MILLISECONDS);
                if (!offered) {
                    consumer.pause(consumer.assignment());  // إيقاف مؤقت بدلاً من التأخر
                }
            }

            // استئناف الاستهلاك إذا أفرغت القائمة بما يكفي
            if (workQueue.size() < 500) {
                consumer.resume(consumer.assignment());
            }

            // الـ heartbeat يُرسل تلقائياً مع كل poll()
        }
    }

    // --- خيوط العمال: تتعامل مع الاستدعاءات البطيئة ---
    public void workerLoop() {
        while (!shutdown) {
            ConsumerRecord<String, Message> record =
                workQueue.poll(500, TimeUnit.MILLISECONDS);

            if (record != null) {
                EnrichedData enriched = enrichmentService.enrich(record.value()); // بطيء لكن لا يؤثر على poll
                processEnrichedRecord(record, enriched);
                commitOffset(record);   // ⚠️ يحتاج تزامناً دقيقاً
            }
        }
    }
}
```

