### معالجة المشكلة من جانب التطبيق أيضاً (Defense in Depth)

```javascript
// لا تثق بالرد أبداً - تحقق قبل التحليل
async function fetchWithValidation(url) {
    const response = await fetch(url);
    const text = await response.text();

    // تحقق من اكتمال JSON قبل التحليل
    const trimmed = text.trim();
    if (!trimmed.endsWith('}') && !trimmed.endsWith(']')) {
        // رد مقتطع - أعد المحاولة
        throw new TruncatedResponseError(
            `Response truncated at ${text.length} bytes`
        );
    }

    try {
        return JSON.parse(text);
    } catch (e) {
        // سجّل النص الكامل للتشخيص
        logger.error('JSON parse failed', { 
            url, 
            length: text.length,
            tail: text.slice(-100)  // آخر 100 حرف للتشخيص
        });
        throw e;
    }
}
```

```python
# Python - نفس المبدأ
import json
import logging

def safe_parse_response(response):
    text = response.text

    if not text.rstrip().endswith(('}', ']')):
        logging.error(
            "Truncated response detected",
            extra={
                "url": response.url,
                "length": len(text),
                "status": response.status_code,
                "content_length": response.headers.get('Content-Length'),
                "actual_length": len(text.encode('utf-8'))
            }
        )
        raise ValueError(f"Response appears truncated: {len(text)} bytes")

    return json.loads(text)
```

