### الخطوة 2: اكتشاف المشكلة في الـ Client

```swift
// iOS - تسجيل الردود الناقصة
class APIClient {
    func request(_ endpoint: String) async throws -> Data {
        let (data, response) = try await URLSession.shared.data(from: url)

        guard let httpResponse = response as? HTTPURLResponse else {
            throw APIError.invalidResponse
        }

        // تحقق من Content-Length
        if let contentLengthStr = httpResponse.value(forHTTPHeaderField: "Content-Length"),
           let contentLength = Int(contentLengthStr),
           data.count != contentLength {

            // سجّل المشكلة قبل الـ crash
            Logger.error("""
                JSON مقتطع!
                متوقع: \(contentLength) bytes
                مستلم: \(data.count) bytes
                endpoint: \(endpoint)
                request-id: \(httpResponse.value(forHTTPHeaderField: "X-Request-ID") ?? "none")
            """)

            throw APIError.truncatedResponse(expected: contentLength, received: data.count)
        }

        return data
    }
}
```

