## الحل الدفاعي في الـ Client

```kotlin
// Android - Kotlin
// لا تعتمد على Content-Length فقط، تحقق من صحة JSON

fun parseResponse(responseBody: String): Result<ApiResponse> {
    // تحقق سريع قبل التحليل الكامل
    val trimmed = responseBody.trim()

    val isValidJson = when {
        trimmed.startsWith("{") && !trimmed.endsWith("}") -> false
        trimmed.startsWith("[") && !trimmed.endsWith("]") -> false
        trimmed.isEmpty() -> false
        else -> true
    }

    if (!isValidJson) {
        // أرسل تقرير للـ monitoring
        Analytics.track("truncated_json", mapOf(
            "length" to responseBody.length,
            "preview" to responseBody.takeLast(100)
        ))
        return Result.failure(TruncatedResponseException())
    }

    return try {
        Result.success(gson.fromJson(responseBody, ApiResponse::class.java))
    } catch (e: JsonParseException) {
        Result.failure(e)
    }
}
```

