### المستوى 2: إصلاح تسرب الذاكرة في الكود

```java
// ❌ المشكلة الشائعة: تراكم الكائنات في الـ cache
public class GrpcServiceImpl extends ServiceGrpc.ServiceImplBase {

    // هذا يتراكم إلى الأبد!
    private final Map<String, ResponseData> cache = new HashMap<>();

    @Override
    public void processRequest(Request req, StreamObserver<Response> observer) {
        String key = req.getId();
        ResponseData data = expensiveComputation(req);
        cache.put(key, data); // ❌ لا يُحذف أبداً
        observer.onNext(buildResponse(data));
        observer.onCompleted();
    }
}
```

```java
// ✅ الحل: استخدام Caffeine Cache مع حدود واضحة
import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;

public class GrpcServiceImpl extends ServiceGrpc.ServiceImplBase {

    private final Cache<String, ResponseData> cache = Caffeine.newBuilder()
        .maximumSize(10_000)
        .expireAfterWrite(Duration.ofMinutes(5))
        .expireAfterAccess(Duration.ofMinutes(2))
        .recordStats() // للمراقبة
        .build();

    @Override
    public void processRequest(Request req, StreamObserver<Response> observer) {
        ResponseData data = cache.get(req.getId(), 
            key -> expensiveComputation(req));
        observer.onNext(buildResponse(data));
        observer.onCompleted();
    }
}
```

```java
// ❌ مشكلة شائعة أخرى: الـ interceptors تحتفظ بـ context
public class LoggingInterceptor implements ServerInterceptor {

    // ❌ تراكم بيانات كل طلب
    private final List<RequestMetadata> allRequests = new ArrayList<>();

    @Override
    public <Req, Resp> ServerCall.Listener<Req> interceptCall(
            ServerCall<Req, Resp> call,
            Metadata headers,
            ServerCallHandler<Req, Resp> next) {

        RequestMetadata meta = new RequestMetadata(call, headers);
        allRequests.add(meta); // ❌ لا يُنظَّف أبداً
        return next.startCall(call, headers);
    }
}
```

```java
// ✅ الحل: استخدام Context بشكل صحيح
public class LoggingInterceptor implements ServerInterceptor {

    private static final Context.Key<RequestMetadata> REQUEST_META = 
        Context.key("request-metadata");

    @Override
    public <Req, Resp> ServerCall.Listener<Req> interceptCall(
            ServerCall<Req, Resp> call,
            Metadata headers,
            ServerCallHandler<Req, Resp> next) {

        // Context يُنظَّف تلقائياً عند انتهاء الطلب
        Context ctx = Context.current()
            .withValue(REQUEST_META, new RequestMetadata(call, headers));

        return Contexts.interceptCall(ctx, call, headers, next);
    }
}
```

