### المستوى 3: إدارة الـ Streaming بشكل صحيح

```java
// ❌ مشكلة: تجميع كل البيانات في الذاكرة
public class DataStreamService extends DataServiceGrpc.DataServiceImplBase {

    @Override
    public void streamData(Request req, StreamObserver<DataChunk> observer) {
        // ❌ تحميل كل شيء دفعة واحدة
        List<DataChunk> allData = database.fetchAll(req.getQuery()); // قد يكون GBs!

        for (DataChunk chunk : allData) {
            observer.onNext(chunk);
        }
        observer.onCompleted();
    }
}
```

```java
// ✅ الحل: Backpressure-aware streaming
public class DataStreamService extends DataServiceGrpc.DataServiceImplBase {

    @Override
    public void streamData(Request req, StreamObserver<DataChunk> responseObserver) {

        ServerCallStreamObserver<DataChunk> serverObserver = 
            (ServerCallStreamObserver<DataChunk>) responseObserver;

        // تفعيل manual flow control
        serverObserver.disableAutoInboundFlowControl();

        AtomicBoolean wasReady = new AtomicBoolean(false);

        serverObserver.setOnReadyHandler(() -> {
            if (serverObserver.isReady() && wasReady.compareAndSet(false, true)) {
                streamInBatches(req, serverObserver, wasReady);
            }
        });
    }

    private void streamInBatches(
            Request req,
            ServerCallStreamObserver<DataChunk> observer,
            AtomicBoolean wasReady) {

        try (var cursor = database.streamQuery(req.getQuery())) {
            // معالجة على دفعات صغيرة
            List<DataChunk> batch = new ArrayList<>(100);

            cursor.forEachRemaining(record -> {
                batch.add(convertToChunk(record));

                if (batch.size() >= 100) {
                    if (!observer.isReady()) {
                        // انتظر حتى يكون العميل جاهزاً
                        wasReady.set(false);
                        return;
                    }
                    batch.forEach(observer::onNext);
                    batch.clear();

                    // السماح لـ GC بتنظيف الدفعة
                    // لا تراكم في الذاكرة
                }
            });

            // إرسال ما تبقى
            batch.forEach(observer::onNext);
            observer.onCompleted();

        } catch (Exception e) {
            observer.onError(Status.INTERNAL
                .withDescription(e.getMessage())
                .asRuntimeException());
        }
    }
}
```

