### المستوى 4: Object Pooling للكائنات الكبيرة

```java
// ✅ إعادة استخدام الـ buffers بدلاً من إنشاء جديدة
import io.netty.buffer.PooledByteBufAllocator;

@Configuration
public class GrpcServerConfig {

    @Bean
    public Server grpcServer(List<BindableService> services) {
        return NettyServerBuilder.forPort(9090)
            // استخدام Pooled allocator
            .channelType(NioServerSocketChannel.class)
            .withOption(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
            // ضبط حجم الـ thread pool
            .executor(buildOptimizedExecutor())
            // تحديد حجم الرسائل
            .maxInboundMessageSize(4 * 1024 * 1024) // 4MB
            .maxInboundMetadataSize(8 * 1024)        // 8KB
            .build();
    }

    private Executor buildOptimizedExecutor() {
        return new ThreadPoolExecutor(
            Runtime.getRuntime().availableProcessors(),      // core
            Runtime.getRuntime().availableProcessors() * 4,  // max
            60L, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(1000), // حد للطابور
            new ThreadFactory() {
                private final AtomicInteger count = new AtomicInteger();
                public Thread newThread(Runnable r) {
                    Thread t = new Thread(r, "grpc-worker-" + count.incrementAndGet());
                    t.setDaemon(true);
                    return t;
                }
            },
            new ThreadPoolExecutor.CallerRunsPolicy() // backpressure
        );
    }
}
