## الحلول حسب الأولوية

### ✅ الحل الفوري — إضافة Mutex (الأسرع والأأمن)

```swift
// Swift
class DataManager {
    // قبل الإصلاح ❌
    var sharedDict: [String: Any] = [:]

    // بعد الإصلاح ✅
    private let lock = NSLock()
    private var sharedDict: [String: Any] = [:]

    func updateFromCallback(_ key: String, _ value: Any) {
        lock.lock()
        defer { lock.unlock() }  // يضمن الفتح حتى عند الخطأ
        sharedDict[key] = value
    }

    func readValue(for key: String) -> Any? {
        lock.lock()
        defer { lock.unlock() }
        return sharedDict[key]
    }
}
```

```kotlin
// Kotlin/Android
class DataManager {
    // قبل الإصلاح ❌
    val sharedDict = mutableMapOf<String, Any>()

    // بعد الإصلاح ✅
    private val lock = ReentrantReadWriteLock()
    private val sharedDict = mutableMapOf<String, Any>()

    fun updateFromCallback(key: String, value: Any) {
        lock.writeLock().lock()
        try {
            sharedDict[key] = value
        } finally {
            lock.writeLock().unlock()
        }
    }

    fun readValue(key: String): Any? {
        lock.readLock().lock()
        try {
            return sharedDict[key]
        } finally {
            lock.readLock().unlock()
        }
    }
}
```

