// Swift — استخدام Actor (iOS 15+)
actor SharedDataStore {
    private var dict: [String: Any] = [:]

    func update(key: String, value: Any) {
        dict[key] = value  // Actor يضمن التسلسل تلقائياً
    }

    func read(key: String) -> Any? {
        return dict[key]
    }
}

// الاستخدام
let store = SharedDataStore()

func sdkCallback(key: String, value: Any) {
    Task {
        await store.update(key: key, value: value)
    }
}
